#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

void* download(void* arg) {
    int id = *(int*)arg;
    usleep(200000);               // 200 ms simulated download
    printf("Image %d done\n", id);
    return NULL;
}

int main() {
    const int N = 4;
    pthread_t th[N];
    int ids[N];
    for (int i = 0; i < N; ++i) {
        ids[i] = i + 1;
        pthread_create(&th[i], NULL, download, &ids[i]);
    }
    for (int i = 0; i < N; ++i) {
        pthread_join(th[i], NULL);
    }
    printf("All downloads complete\n");
    return 0;
}

